local d=...;d=d or "";local function g(u)local r,e=http.get(u,nil,true)if not r then error(u.." -> "..tostring(e),0)end local b=r.readAll()r.close()return b end local t=textutils.unserialiseJSON(g("https://api.github.com/repos/Luedalsa/ComputerCraft/git/trees/master?recursive=1"))if not t or not t.tree then error("Respuesta inesperada de la API",0)end if t.truncated then print("Aviso: lista incompleta")end for _,i in ipairs(t.tree)do if i.type=="blob"then local p=fs.combine(d,i.path)local D=fs.getDir(p)if D~=""then fs.makeDir(D)end local f=assert(fs.open(p,"wb"))f.write(g("https://raw.githubusercontent.com/Luedalsa/ComputerCraft/master/"..i.path))f.close()print("OK "..i.path)end end